<?php
require_once __DIR__ . '/../includes/auth.php'; require_login('employee'); $user = current_user(); $error = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $name = trim($_POST['full_name'] ?? ''); $phone = trim($_POST['phone'] ?? ''); if (!$name) { $error = 'Name cannot be empty.'; } else { $statement = db()->prepare('UPDATE users SET full_name = ?, phone = ?, avatar_initials = ? WHERE id = ?'); $statement->execute([$name, $phone, make_avatar_initials($name), $user['id']]); flash('success', 'Your profile has been updated.'); header('Location: ' . base_url('employee/profile.php')); exit; } }
$pageTitle = 'My profile'; require __DIR__ . '/../includes/header.php';
?><div class="page-content"><div class="detail-heading"><div><span class="eyebrow">Account / Personal details</span><h2>My profile</h2><p class="muted mb-0">Keep your contact information current.</p></div></div><section class="panel form-card"><?php if ($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post" class="stack-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="d-flex gap-3 align-items-center mb-2"><span class="avatar" style="width:52px;height:52px;font-size:16px"><?= e($user['avatar_initials']) ?></span><div><strong><?= e($user['employee_code']) ?></strong><div class="helper"><?= e($user['department']) ?> · <?= e($user['job_title']) ?></div></div></div><label>Full name<input name="full_name" value="<?= e($user['full_name']) ?>" required></label><label>Work email<input value="<?= e($user['email']) ?>" disabled></label><label>Phone number<input name="phone" value="<?= e($user['phone']) ?>"></label><div><button class="btn btn-primary" type="submit">Save changes</button></div></form></section></div><?php require __DIR__ . '/../includes/footer.php'; ?>
